"""Bounded model checker for the FSM in model.py.

Explores all states reachable from the initial states within k steps
and reports whether any bad state (safety violation) is reachable.

Usage: python3 checker.py [k]
"""

import sys

from model import BAD_STATES, INITIAL_STATES, successors


def check(bound):
    """BFS up to `bound` steps.

    Returns (violated, depth, witness) where `witness` is a path from an
    initial state to a bad state, or None if the property holds within
    the bound. `depth` is the step count at which a bad state was found,
    or `bound` if none was found.
    """
    parents = {state: None for state in INITIAL_STATES}
    frontier = set(INITIAL_STATES)

    for depth in range(bound + 1):
        bad = frontier & BAD_STATES
        if bad:
            return True, depth, _witness(parents, min(bad))
        if depth == bound:
            break
        nxt = set()
        for src in frontier:
            for dst in successors(src) - parents.keys():
                parents[dst] = src
                nxt.add(dst)
        frontier = nxt

    return False, bound, None


def _witness(parents, bad):
    """Reconstruct the path from an initial state to `bad`."""
    path = []
    while bad is not None:
        path.append(bad)
        bad = parents[bad]
    return list(reversed(path))


def main():
    if len(sys.argv) > 2:
        sys.exit(f"usage: {sys.argv[0]} [k]")
    try:
        bound = int(sys.argv[1]) if len(sys.argv) == 2 else 10
    except ValueError:
        sys.exit(f"usage: {sys.argv[0]} [k]")
    if bound < 0:
        sys.exit("bound k must be >= 0")

    violated, depth, witness = check(bound)

    print(f"BMC bound k = {bound}")
    if violated:
        print(f"result: PROPERTY VIOLATED — bad state reachable in {depth} step(s)")
        print("witness path:")
        for i, state in enumerate(witness):
            print(f"  {i}: {state}")
    else:
        print(f"result: property holds — no bad state reachable within {bound} step(s)")


if __name__ == "__main__":
    main()
